const sanitizeHexValue = (value = '') => value.replace(/[^0-9a-f]/gi, '').slice(0, 6)

const expandHexValue = (value) =>
  value.length === 3
    ? value
        .split('')
        .map((character) => `${character}${character}`)
        .join('')
    : value

const isCompleteHexValue = (value) => value.length === 3 || value.length === 6

const normalizeHexValue = (value, fallback = '#ffffff') => {
  const sanitizedValue = sanitizeHexValue(value)

  if (!isCompleteHexValue(sanitizedValue)) {
    return fallback
  }

  return `#${expandHexValue(sanitizedValue).toLowerCase()}`
}

const hexToRgb = (hex) => {
  const normalizedHex = normalizeHexValue(hex).replace('#', '')

  return {
    r: Number.parseInt(normalizedHex.slice(0, 2), 16),
    g: Number.parseInt(normalizedHex.slice(2, 4), 16),
    b: Number.parseInt(normalizedHex.slice(4, 6), 16),
  }
}

const rgbToHex = (r, g, b) =>
  `#${[r, g, b]
    .map((value) => clampValue(Math.round(value), 0, 255).toString(16).padStart(2, '0'))
    .join('')}`

const rgbToHsv = (r, g, b) => {
  const rn = r / 255
  const gn = g / 255
  const bn = b / 255
  const max = Math.max(rn, gn, bn)
  const min = Math.min(rn, gn, bn)
  const delta = max - min
  let h = 0

  if (delta !== 0) {
    switch (max) {
      case rn:
        h = 60 * (((gn - bn) / delta) % 6)
        break
      case gn:
        h = 60 * ((bn - rn) / delta + 2)
        break
      default:
        h = 60 * ((rn - gn) / delta + 4)
        break
    }
  }

  if (h < 0) {
    h += 360
  }

  const s = max === 0 ? 0 : (delta / max) * 100
  const v = max * 100

  return { h, s, v }
}

const hsvToRgb = (h, s, v) => {
  const sn = clampValue(s, 0, 100) / 100
  const vn = clampValue(v, 0, 100) / 100
  const c = vn * sn
  const hh = ((h % 360) + 360) % 360 / 60
  const x = c * (1 - Math.abs((hh % 2) - 1))
  let rn = 0
  let gn = 0
  let bn = 0

  if (hh >= 0 && hh < 1) {
    rn = c
    gn = x
  } else if (hh >= 1 && hh < 2) {
    rn = x
    gn = c
  } else if (hh >= 2 && hh < 3) {
    gn = c
    bn = x
  } else if (hh >= 3 && hh < 4) {
    gn = x
    bn = c
  } else if (hh >= 4 && hh < 5) {
    rn = x
    bn = c
  } else {
    rn = c
    bn = x
  }

  const m = vn - c

  return {
    r: (rn + m) * 255,
    g: (gn + m) * 255,
    b: (bn + m) * 255,
  }
}

const hexToHsv = (hex) => {
  const { r, g, b } = hexToRgb(hex)
  return rgbToHsv(r, g, b)
}

const hsvToHex = (h, s, v) => {
  const { r, g, b } = hsvToRgb(h, s, v)
  return rgbToHex(r, g, b)
}

const rgbToHsl = (r, g, b) => {
  const rn = r / 255
  const gn = g / 255
  const bn = b / 255
  const max = Math.max(rn, gn, bn)
  const min = Math.min(rn, gn, bn)
  let h = 0
  let s = 0
  const l = (max + min) / 2
  const delta = max - min

  if (delta !== 0) {
    s = delta / (1 - Math.abs(2 * l - 1))

    switch (max) {
      case rn:
        h = 60 * (((gn - bn) / delta) % 6)
        break
      case gn:
        h = 60 * ((bn - rn) / delta + 2)
        break
      default:
        h = 60 * ((rn - gn) / delta + 4)
        break
    }
  }

  if (h < 0) {
    h += 360
  }

  return [h, s * 100, l * 100]
}

const hslToRgb = (h, s, l) => {
  const sn = clampValue(s, 0, 100) / 100
  const ln = clampValue(l, 0, 100) / 100
  const c = (1 - Math.abs(2 * ln - 1)) * sn
  const hh = h / 60
  const x = c * (1 - Math.abs((hh % 2) - 1))
  let rn = 0
  let gn = 0
  let bn = 0

  if (hh >= 0 && hh < 1) {
    rn = c
    gn = x
  } else if (hh >= 1 && hh < 2) {
    rn = x
    gn = c
  } else if (hh >= 2 && hh < 3) {
    gn = c
    bn = x
  } else if (hh >= 3 && hh < 4) {
    gn = x
    bn = c
  } else if (hh >= 4 && hh < 5) {
    rn = x
    bn = c
  } else {
    rn = c
    bn = x
  }

  const m = ln - c / 2

  return [
    Math.round((rn + m) * 255),
    Math.round((gn + m) * 255),
    Math.round((bn + m) * 255),
  ]
}

const applyAdjustmentsToHex = (hex, adjustments = {}) => {
  const normalizedHex = normalizeHexValue(hex)
  const { r, g, b } = hexToRgb(normalizedHex)
  const [h, s, l] = rgbToHsl(r, g, b)
  const adjustedHue = (h + (Number(adjustments.hueShift) || 0) + 360) % 360
  const adjustedSaturation = clampValue(s + (Number(adjustments.saturation) || 0), 0, 100)
  const adjustedLightness = clampValue(l + (Number(adjustments.lightness) || 0), 0, 100)
  const [nr, ng, nb] = hslToRgb(adjustedHue, adjustedSaturation, adjustedLightness)

  return rgbToHex(nr, ng, nb)
}

const buildPartPreviewAdjustments = (part, overrides = {}) => ({
  hueShift: overrides.hueShift ?? part?.hueShift ?? 0,
  saturation: overrides.saturation ?? part?.saturation ?? 0,
  lightness: overrides.lightness ?? part?.lightness ?? 0,
  opacity: overrides.opacity ?? part?.opacity ?? 100,
  contrast: overrides.contrast ?? part?.contrast ?? 0,
})

const getPartPreviewTintHex = (part, overrides = {}) =>
  overrides.tintHex ??
  part?.tintHex ??
  getSelectionHex(overrides.selection ?? part?.selection, '#ffffff')

const buildPartPreviewImage = async (layer, part, overrides = null) => {
  if (!layer || !part || isEmptyColorSelection(part.selection)) {
    return null
  }

  const partMeta = getAssetPartMeta(layer.layerType, layer.assetName, part.key)
  if (!partMeta) {
    return null
  }

  const sourceImage = getAssetImagePath(layer.layerType, layer.assetName, part.key)
  if (!sourceImage) {
    return null
  }

  return processImageColor(
    sourceImage,
    getPartPreviewTintHex(part, overrides || {}),
    buildPartPreviewAdjustments(part, overrides || {}),
    {
      tintMode: partMeta.tintMode || 'luminance-map',
    }
  )
}

const collectPreviewLayerImages = async (
  layer,
  previewPartKey = null,
  previewOverrides = null,
  allowOverrides = true
) => {
  if (!layer?.display) {
    return []
  }

  const partImages = await Promise.all(
    (layer.parts || []).map((part) => {
      const overrides =
        allowOverrides && part.key === previewPartKey ? previewOverrides : null
      return buildPartPreviewImage(layer, part, overrides)
    })
  )

  const mergedImages = partImages.filter(Boolean)

  for (const additionalLayer of layer.additional || []) {
    const additionalImages = await collectPreviewLayerImages(
      additionalLayer,
      previewPartKey,
      previewOverrides,
      false
    )
    mergedImages.push(...additionalImages)
  }

  return mergedImages
}

const buildCompositePreviewImage = async (
  layers,
  targetLayerId = null,
  previewPartKey = null,
  previewOverrides = null,
  applyAcrossLayers = false
) => {
  const previewImages = []

  for (const layer of layers || []) {
    const layerImages = await collectPreviewLayerImages(
      layer,
      previewPartKey,
      previewOverrides,
      Boolean(previewOverrides) &&
        (applyAcrossLayers || layer.id === targetLayerId)
    )

    previewImages.push(...layerImages)
  }

  if (!previewImages.length) {
    return ''
  }

  if (previewImages.length === 1) {
    return previewImages[0]
  }

  return mergeImages(previewImages)
}

const ColorSelectModal = ({
  open,
  onClose,
  options,
  selection,
  partKey,
  layerId,
  previewLayerIds = null,
  applyPreviewAcrossLayers = false,
  onSelectColor = null,
  onApplyColorTool = null,
  onResetColorTool = null,
}) => {
  const layerArr = useLayerStore((state) => state.layerArr)
  const recentTintHexes = useLayerStore((state) => state.recentTintHexes)
  const selectedLayer = useLayerStore((state) => state.selectedLayer)
  const pushRecentTintHex = useLayerStore((state) => state.pushRecentTintHex)
  const setLayerPartTintHex = useLayerStore((state) => state.setLayerPartTintHex)
  const setLayerPartColorAdjustments = useLayerStore(
    (state) => state.setLayerPartColorAdjustments
  )
  const setLayerAllPartAppearance = useLayerStore(
    (state) => state.setLayerAllPartAppearance
  )
  const [pickerHue, setPickerHue] = useState(0)
  const [pickerSaturation, setPickerSaturation] = useState(0)
  const [pickerValue, setPickerValue] = useState(100)
  const [hexInputValue, setHexInputValue] = useState('FFFFFF')
  const [previewOpacity, setPreviewOpacity] = useState(100)
  const [previewContrast, setPreviewContrast] = useState(0)
  const [currentPreviewImage, setCurrentPreviewImage] = useState('')
  const [nextPreviewImage, setNextPreviewImage] = useState('')
  const [dragMode, setDragMode] = useState(null)
  const saturationValueRef = useRef(null)
  const hueRailRef = useRef(null)

  const activeLayerId = layerId ?? selectedLayer
  const selectedLayerData = layerArr.find((layer) => layer.id === activeLayerId)
  const previewLayers = useMemo(() => {
    if (Array.isArray(previewLayerIds) && previewLayerIds.length > 0) {
      return previewLayerIds
        .map((previewLayerId) => layerArr.find((layer) => layer.id === previewLayerId))
        .filter(Boolean)
    }

    return selectedLayerData ? [selectedLayerData] : []
  }, [layerArr, previewLayerIds, selectedLayerData])
  const resolvedPartKey = partKey || selectedLayerData?.parts?.[0]?.key
  const selectedPart = selectedLayerData?.parts?.find(
    (part) => part.key === resolvedPartKey
  )
  const currentTintHex = selectedPart?.tintHex || null
  const currentHueShift = selectedPart?.hueShift || 0
  const currentSaturation = selectedPart?.saturation || 0
  const currentLightness = selectedPart?.lightness || 0
  const currentOpacity = selectedPart?.opacity ?? 100
  const currentContrast = selectedPart?.contrast ?? 0
  const baseBodyLayer = layerArr.find(
    (layer) => layer.layerType === 'Body' && layer.isBaseLayer
  )

  const selectedColorHex = useMemo(
    () => getSelectionHex(selection, '#ffffff'),
    [selection]
  )

  const skinMatchHex = useMemo(
    () => getPartPreviewHex(baseBodyLayer?.parts?.[0], '#f3d6ba'),
    [baseBodyLayer]
  )

  const presetOptions = useMemo(() => {
    const uniqueOptions = Array.from(new Set(options || []))
    const visibleOptions = uniqueOptions.filter(
      (colorOption) => !isEmptyColorSelection(colorOption)
    )
    const hiddenOptions = uniqueOptions.filter((colorOption) =>
      isEmptyColorSelection(colorOption)
    )

    return [...visibleOptions, ...hiddenOptions]
  }, [options])

  const initialToolHex = useMemo(
    () =>
      applyAdjustmentsToHex(currentTintHex || selectedColorHex, {
        hueShift: currentHueShift,
        saturation: currentSaturation,
        lightness: currentLightness,
      }),
    [
      currentHueShift,
      currentLightness,
      currentSaturation,
      currentTintHex,
      selectedColorHex,
    ]
  )

  const previewTintHex = useMemo(
    () => hsvToHex(pickerHue, pickerSaturation, pickerValue),
    [pickerHue, pickerSaturation, pickerValue]
  )

  const pickerHueColor = useMemo(() => hsvToHex(pickerHue, 100, 100), [pickerHue])

  const syncPickerFromHex = (hexValue) => {
    const normalizedHex = normalizeHexValue(hexValue)
    const { h, s, v } = hexToHsv(normalizedHex)
    setPickerHue(h)
    setPickerSaturation(s)
    setPickerValue(v)
    setHexInputValue(normalizedHex.replace('#', '').toUpperCase())
  }

  useEffect(() => {
    if (open) {
      syncPickerFromHex(initialToolHex)
      setPreviewOpacity(currentOpacity)
      setPreviewContrast(currentContrast)
    } else {
      setCurrentPreviewImage('')
      setNextPreviewImage('')
      setDragMode(null)
    }
  }, [open, currentContrast, currentOpacity, initialToolHex])

  useEffect(() => {
    if (!open) {
      return
    }

    setHexInputValue(previewTintHex.replace('#', '').toUpperCase())
  }, [previewTintHex, open])

  useEffect(() => {
    let isCurrent = true

    const renderLivePreview = async () => {
      if (!open || !selectedLayerData || !resolvedPartKey) {
        if (isCurrent) {
          setCurrentPreviewImage('')
          setNextPreviewImage('')
        }
        return
      }

      const [processedCurrentPreview, processedNextPreview] = await Promise.all([
        buildCompositePreviewImage(previewLayers, activeLayerId),
        buildCompositePreviewImage(previewLayers, activeLayerId, resolvedPartKey, {
          tintHex: previewTintHex,
          hueShift: 0,
          saturation: 0,
          lightness: 0,
          opacity: previewOpacity,
          contrast: previewContrast,
        }, applyPreviewAcrossLayers),
      ])

      if (isCurrent) {
        setCurrentPreviewImage(processedCurrentPreview)
        setNextPreviewImage(processedNextPreview)
      }
    }

    renderLivePreview()

    return () => {
      isCurrent = false
    }
  }, [
    currentHueShift,
    currentLightness,
    currentContrast,
    currentOpacity,
    currentSaturation,
    currentTintHex,
    open,
    previewLayers,
    previewTintHex,
    resolvedPartKey,
    selectedLayerData,
    previewOpacity,
    previewContrast,
    activeLayerId,
    applyPreviewAcrossLayers,
  ])

  const updateSaturationValueFromPointer = (clientX, clientY) => {
    if (!saturationValueRef.current) {
      return
    }

    const { left, top, width, height } = saturationValueRef.current.getBoundingClientRect()
    const nextSaturation = clampValue(((clientX - left) / width) * 100, 0, 100)
    const nextValue = clampValue(100 - ((clientY - top) / height) * 100, 0, 100)

    setPickerSaturation(nextSaturation)
    setPickerValue(nextValue)
  }

  const updateHueFromPointer = (clientY) => {
    if (!hueRailRef.current) {
      return
    }

    const { top, height } = hueRailRef.current.getBoundingClientRect()
    const nextHue = clampValue(((clientY - top) / height) * 360, 0, 360)
    setPickerHue(nextHue === 360 ? 0 : nextHue)
  }

  useEffect(() => {
    if (!dragMode) {
      return
    }

    const handlePointerMove = (event) => {
      if (dragMode === 'sv') {
        updateSaturationValueFromPointer(event.clientX, event.clientY)
      }

      if (dragMode === 'hue') {
        updateHueFromPointer(event.clientY)
      }
    }

    const stopDragging = () => {
      setDragMode(null)
    }

    window.addEventListener('pointermove', handlePointerMove)
    window.addEventListener('pointerup', stopDragging)

    return () => {
      window.removeEventListener('pointermove', handlePointerMove)
      window.removeEventListener('pointerup', stopDragging)
    }
  }, [dragMode])

  const handleHexInputChange = (event) => {
    const sanitizedValue = sanitizeHexValue(event.target.value)
    setHexInputValue(sanitizedValue.toUpperCase())

    if (!isCompleteHexValue(sanitizedValue)) {
      return
    }

    const { h, s, v } = hexToHsv(sanitizedValue)
    setPickerHue(h)
    setPickerSaturation(s)
    setPickerValue(v)
  }

  const handleHexInputBlur = () => {
    setHexInputValue(previewTintHex.replace('#', '').toUpperCase())
  }

  const handleOpacityChange = (event) => {
    setPreviewOpacity(Number(event.target.value))
  }

  const handleContrastChange = (event) => {
    setPreviewContrast(Number(event.target.value))
  }

  const handleRecentColorClick = (hex) => {
    syncPickerFromHex(hex)
    pushRecentTintHex(hex)
  }

  const handleMatchSkin = () => {
    if (!skinMatchHex) {
      return
    }

    syncPickerFromHex(skinMatchHex)
  }

  const applyColorTool = () => {
    if (activeLayerId === null || activeLayerId === undefined || !resolvedPartKey) {
      return
    }

    const normalizedSelected = (selectedColorHex || '').toLowerCase()
    const normalizedTint = (previewTintHex || '').toLowerCase()
    const tintValue = normalizedTint === normalizedSelected ? null : previewTintHex

    if (onApplyColorTool) {
      onApplyColorTool({
        selection,
        tintHex: tintValue,
        adjustments: {
          hueShift: 0,
          saturation: 0,
          lightness: 0,
          opacity: previewOpacity,
          contrast: previewContrast,
        },
      })
      pushRecentTintHex(previewTintHex)
      return
    }

    setLayerPartTintHex(activeLayerId, resolvedPartKey, tintValue)
    setLayerPartColorAdjustments(activeLayerId, resolvedPartKey, {
      hueShift: 0,
      saturation: 0,
      lightness: 0,
      opacity: previewOpacity,
      contrast: previewContrast,
    })
    pushRecentTintHex(previewTintHex)
  }

  const resetColorTool = () => {
    if (activeLayerId === null || activeLayerId === undefined || !resolvedPartKey) {
      return
    }

    if (onResetColorTool) {
      onResetColorTool({
        selection,
      })
      syncPickerFromHex(selectedColorHex)
      setPreviewOpacity(100)
      setPreviewContrast(0)
      return
    }

    setLayerPartTintHex(activeLayerId, resolvedPartKey, null)
    setLayerPartColorAdjustments(activeLayerId, resolvedPartKey, {
      hueShift: 0,
      saturation: 0,
      lightness: 0,
      opacity: 100,
      contrast: 0,
    })
    syncPickerFromHex(selectedColorHex)
    setPreviewOpacity(100)
    setPreviewContrast(0)
  }

  const applyColorToolToAllLayers = () => {
    if (activeLayerId === null || activeLayerId === undefined || !selectedLayerData?.parts?.length) {
      return
    }

    setLayerAllPartAppearance(activeLayerId, {
      tintHex: previewTintHex,
      adjustments: {
        hueShift: 0,
        saturation: 0,
        lightness: 0,
        opacity: previewOpacity,
        contrast: previewContrast,
      },
    })
    pushRecentTintHex(previewTintHex)
  }

  return (
    <Modal open={open} onClose={onClose} hideBackdrop disableAutoFocus>
      <StyledContainer>
        <ColorModalViewport>
          <ColorModalShell>
            <BorderContainer>
              <InnerModal>
                <CloseRow>
                  <CloseButton onClick={onClose} />
                </CloseRow>
                <TintUtilityContainer>
                  <PickerLayout>
                    <PickerColumn>
                      <PickerCanvasRow>
                        <SaturationValueArea
                          ref={saturationValueRef}
                          hueColor={pickerHueColor}
                          onPointerDown={(event) => {
                            updateSaturationValueFromPointer(event.clientX, event.clientY)
                            setDragMode('sv')
                          }}
                        >
                          <SaturationValueThumb
                            left={pickerSaturation}
                            top={100 - pickerValue}
                          />
                        </SaturationValueArea>
                        <HueRail
                          ref={hueRailRef}
                          onPointerDown={(event) => {
                            updateHueFromPointer(event.clientY)
                            setDragMode('hue')
                          }}
                        >
                          <HueThumb top={(pickerHue / 360) * 100} />
                        </HueRail>
                      </PickerCanvasRow>
                      <HexRow>
                        <HexLabel>Hex #</HexLabel>
                        <HexInputShell>
                          <HexPrefix>#</HexPrefix>
                          <HexInput
                            value={hexInputValue}
                            onChange={handleHexInputChange}
                            onBlur={handleHexInputBlur}
                            maxLength={6}
                            spellCheck={false}
                          />
                        </HexInputShell>
                      </HexRow>
                      <UtilityButtonRow>
                        <UtilityButton onClick={() => handleMatchSkin()}>
                          <span>Match Skin</span>
                        </UtilityButton>
                      </UtilityButtonRow>
                    </PickerColumn>
                    <PreviewColumn>
                      <ComparePreviewGrid>
                        <ComparePreviewCard>
                          <ComparePreviewLabel>Current</ComparePreviewLabel>
                          <LivePreviewBox>
                            <BorderContainer inner='white'>
                              <LivePreviewImage importedImage={currentPreviewImage} />
                            </BorderContainer>
                          </LivePreviewBox>
                          <PreviewSwatch color={initialToolHex} />
                        </ComparePreviewCard>
                        <ComparePreviewCard>
                          <ComparePreviewLabel>New</ComparePreviewLabel>
                          <LivePreviewBox>
                            <BorderContainer inner='white'>
                              <LivePreviewImage importedImage={nextPreviewImage} />
                            </BorderContainer>
                          </LivePreviewBox>
                          <PreviewSwatch color={previewTintHex} />
                        </ComparePreviewCard>
                      </ComparePreviewGrid>
                      <SliderStack>
                        <SliderRow>
                          <SliderLabelRow>
                            <SliderLabel>Opacity</SliderLabel>
                            <SliderValue>{previewOpacity}%</SliderValue>
                          </SliderLabelRow>
                          <SliderInput
                            type='range'
                            min='0'
                            max='100'
                            step='1'
                            value={previewOpacity}
                            onChange={handleOpacityChange}
                          />
                        </SliderRow>
                        <SliderRow>
                          <SliderLabelRow>
                            <SliderLabel>Contrast</SliderLabel>
                            <SliderValue>{previewContrast}</SliderValue>
                          </SliderLabelRow>
                          <SliderInput
                            type='range'
                            min='-100'
                            max='100'
                            step='1'
                            value={previewContrast}
                            onChange={handleContrastChange}
                          />
                        </SliderRow>
                      </SliderStack>
                      <TintButtonRow>
                        <TintButton onClick={() => applyColorTool()}>
                          <span>Apply</span>
                        </TintButton>
                        {selectedLayerData?.parts?.length > 1 && (
                          <TintButton onClick={() => applyColorToolToAllLayers()}>
                            <span>Apply to All Layers</span>
                          </TintButton>
                        )}
                        <TintButton onClick={() => resetColorTool()}>
                          <span>Reset</span>
                        </TintButton>
                      </TintButtonRow>
                    </PreviewColumn>
                  </PickerLayout>
                </TintUtilityContainer>
                {recentTintHexes.length > 0 && (
                  <>
                    <ModalSectionTitle>Recent Colors</ModalSectionTitle>
                    <RecentColorsRow>
                      {recentTintHexes.map((hex) => (
                        <RecentColorButton
                          key={hex}
                          onClick={() => handleRecentColorClick(hex)}
                        >
                          <BorderContainer
                            outer={hex === previewTintHex ? '#c45508' : false}
                            inner='white'
                          >
                            <RecentColorSwatch color={hex} />
                          </BorderContainer>
                        </RecentColorButton>
                      ))}
                    </RecentColorsRow>
                  </>
                )}
                <ModalSectionTitle>Preset Colors</ModalSectionTitle>
                <PresetColorsGrid>
                  {presetOptions.map((colorOption) => (
                    <IndividualColor
                      key={colorOption}
                      color={colorOption}
                      selection={selection}
                      partKey={resolvedPartKey}
                      layerId={activeLayerId}
                      onSelectColor={onSelectColor}
                    />
                  ))}
                </PresetColorsGrid>
              </InnerModal>
            </BorderContainer>
          </ColorModalShell>
        </ColorModalViewport>
      </StyledContainer>
    </Modal>
  )
}

export default ColorSelectModal
