import colors from './colors'
import SkinColors from './skinColors'

const clampValue = (value, min, max) => Math.min(max, Math.max(min, value))

const colorHexByFileName = new Map(
  [...colors, ...SkinColors]
    .filter((colorObject) => colorObject?.fileName && colorObject?.hex)
    .map((colorObject) => [colorObject.fileName, colorObject.hex])
)

const hexToRgb = (hex = '#ffffff') => {
  const normalizedHex = hex.replace('#', '')
  const safeHex =
    normalizedHex.length === 3
      ? normalizedHex
          .split('')
          .map((character) => `${character}${character}`)
          .join('')
      : normalizedHex.padEnd(6, 'f')

  return {
    r: Number.parseInt(safeHex.slice(0, 2), 16),
    g: Number.parseInt(safeHex.slice(2, 4), 16),
    b: Number.parseInt(safeHex.slice(4, 6), 16),
  }
}

const rgbToHex = (r, g, b) =>
  `#${[r, g, b]
    .map((value) => clampValue(Math.round(value), 0, 255).toString(16).padStart(2, '0'))
    .join('')}`

const rgbToHsl = (r, g, b) => {
  const rn = r / 255
  const gn = g / 255
  const bn = b / 255
  const max = Math.max(rn, gn, bn)
  const min = Math.min(rn, gn, bn)
  const delta = max - min
  let h = 0
  let s = 0
  const l = (max + min) / 2

  if (delta !== 0) {
    s = delta / (1 - Math.abs(2 * l - 1))

    switch (max) {
      case rn:
        h = 60 * (((gn - bn) / delta) % 6)
        break
      case gn:
        h = 60 * ((bn - rn) / delta + 2)
        break
      default:
        h = 60 * ((rn - gn) / delta + 4)
        break
    }
  }

  if (h < 0) {
    h += 360
  }

  return [h, s * 100, l * 100]
}

const hslToRgb = (h, s, l) => {
  const sn = clampValue(s, 0, 100) / 100
  const ln = clampValue(l, 0, 100) / 100
  const c = (1 - Math.abs(2 * ln - 1)) * sn
  const hh = h / 60
  const x = c * (1 - Math.abs((hh % 2) - 1))
  let rn = 0
  let gn = 0
  let bn = 0

  if (hh >= 0 && hh < 1) {
    rn = c
    gn = x
  } else if (hh >= 1 && hh < 2) {
    rn = x
    gn = c
  } else if (hh >= 2 && hh < 3) {
    gn = c
    bn = x
  } else if (hh >= 3 && hh < 4) {
    gn = x
    bn = c
  } else if (hh >= 4 && hh < 5) {
    rn = x
    bn = c
  } else {
    rn = c
    bn = x
  }

  const m = ln - c / 2

  return [
    Math.round((rn + m) * 255),
    Math.round((gn + m) * 255),
    Math.round((bn + m) * 255),
  ]
}

const applyAdjustmentsToHex = (hex, adjustments = {}) => {
  const { r, g, b } = hexToRgb(hex || '#ffffff')
  const [h, s, l] = rgbToHsl(r, g, b)
  const adjustedHue = (h + (Number(adjustments.hueShift) || 0) + 360) % 360
  const adjustedSaturation = clampValue(s + (Number(adjustments.saturation) || 0), 0, 100)
  const adjustedLightness = clampValue(l + (Number(adjustments.lightness) || 0), 0, 100)
  const [nr, ng, nb] = hslToRgb(adjustedHue, adjustedSaturation, adjustedLightness)

  return rgbToHex(nr, ng, nb)
}

const getSelectionHex = (selection, fallback = '#ffffff') =>
  colorHexByFileName.get(selection) || fallback

const getPartPreviewHex = (part, fallback = '#ffffff') => {
  const baseHex = part?.tintHex || getSelectionHex(part?.selection, fallback)
  return applyAdjustmentsToHex(baseHex, part)
}

export { getPartPreviewHex, getSelectionHex, applyAdjustmentsToHex }
