import React, { useMemo, useState } from 'react'
import useLayerStore from '../../../utils/store'
import { getAssetPartMeta } from '../../../utils/dataV2'
import { getPartPreviewHex } from '../../../utils/color-display'
import ColorSelectModal from '../color-select-modal/color-select-modal'
import {
  AssetPreview,
  AssetBorder,
  LeftArrow,
  RightArrow,
  ColorPreview,
  ButtonContainer,
  SelectorCard,
  SelectorLabel,
} from './item-options.style'

const FullBodyColorSelector = ({ bodyLayers = [] }) => {
  const setAllBodyColor = useLayerStore((state) => state.setAllBodyColor)
  const setAllBodyAppearance = useLayerStore((state) => state.setAllBodyAppearance)
  const [open, setOpen] = useState(false)
  const primaryBodyLayer = bodyLayers[0] || null
  const bodyPart = primaryBodyLayer?.parts?.[0] || null
  const partMeta = useMemo(
    () =>
      bodyPart
        ? getAssetPartMeta(primaryBodyLayer.layerType, primaryBodyLayer.assetName, bodyPart.key)
        : null,
    [bodyPart, primaryBodyLayer]
  )
  const colorOptions = partMeta?.colorOptions || []
  const currentColorIndex = colorOptions.indexOf(bodyPart?.selection)
  const previewHex = getPartPreviewHex(bodyPart, '#f3d6ba')

  const changeSelection = (direction) => {
    if (!colorOptions.length || !bodyPart) {
      return
    }

    const safeCurrentIndex = currentColorIndex >= 0 ? currentColorIndex : 0
    const nextIndex =
      (safeCurrentIndex + direction + colorOptions.length) % colorOptions.length

    setAllBodyColor(colorOptions[nextIndex])
  }

  if (!primaryBodyLayer || !bodyPart) {
    return null
  }

  return (
    <SelectorCard>
      <SelectorLabel>Full Body</SelectorLabel>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <ButtonContainer onClick={() => changeSelection(-1)}>
          <LeftArrow />
        </ButtonContainer>
        <AssetBorder isSelected={open}>
          <AssetPreview onClick={() => setOpen(true)}>
            <ColorPreview color={previewHex || '#ffffff'} />
          </AssetPreview>
        </AssetBorder>
        <ButtonContainer onClick={() => changeSelection(1)}>
          <RightArrow />
        </ButtonContainer>
      </div>
      <ColorSelectModal
        open={open}
        onClose={() => setOpen(false)}
        options={colorOptions}
        selection={bodyPart.selection}
        partKey={bodyPart.key}
        layerId={primaryBodyLayer.id}
        previewLayerIds={bodyLayers.map((layer) => layer.id)}
        applyPreviewAcrossLayers
        onSelectColor={(color) => setAllBodyColor(color)}
        onApplyColorTool={({ selection, tintHex, adjustments }) =>
          setAllBodyAppearance({
            selection,
            tintHex,
            adjustments,
          })
        }
        onResetColorTool={({ selection }) =>
          setAllBodyAppearance({
            selection,
            tintHex: null,
            adjustments: {
              hueShift: 0,
              saturation: 0,
              lightness: 0,
              opacity: 100,
              contrast: 0,
            },
          })
        }
      />
    </SelectorCard>
  )
}

export default FullBodyColorSelector
