import React from 'react'
import BorderContainer from '../../border-container/border-container'
import useLayerStore from '../../../utils/store'
import { getAssetMeta } from '../../../utils/dataV2'
import FullBodyColorSelector from './full-body-color-selector'
import PartColorSelector from './part-color-selector'
import { OptionsContainer } from '../options.style'
import {
  BodyOptionsContainer,
  BodyOptionsInner,
  BodyFullSelectorRow,
  BodyOptionsTitle,
  BodySelectorsGrid,
  BodySelectorRow,
  BodySelectorCard,
  SelectorLabel,
} from './item-options.style'

const bodyLayoutRows = [['Body_5'], ['Body_6', 'Body_1', 'Body_4'], ['Body_2', 'Body_3']]

const BodyOptions = () => {
  const layerArr = useLayerStore((state) => state.layerArr)
  const bodyLayers = layerArr.filter(
    (layer) => layer.layerType === 'Body' && layer.isBaseLayer
  )
  const bodyLayerMap = new Map(bodyLayers.map((layer) => [layer.assetName, layer]))

  return (
    <OptionsContainer>
      <BorderContainer>
        <BodyOptionsContainer>
          <BodyOptionsInner>
            <BodyFullSelectorRow>
              <FullBodyColorSelector bodyLayers={bodyLayers} />
            </BodyFullSelectorRow>
            <BodyOptionsTitle>Body Colors</BodyOptionsTitle>
            <BodySelectorsGrid>
              {bodyLayoutRows.map((row, rowIndex) => (
                <BodySelectorRow key={`body-row-${rowIndex}`}>
                  {row.map((assetName) => {
                    const layer = bodyLayerMap.get(assetName)
                    if (!layer) {
                      return null
                    }

                    const assetMeta = getAssetMeta('Body', layer.assetName)

                    return (
                      <BodySelectorCard key={layer.assetName}>
                        <SelectorLabel>{assetMeta?.label || layer.assetName}</SelectorLabel>
                        <PartColorSelector
                          layerId={layer.id}
                          layerType={layer.layerType}
                          assetName={layer.assetName}
                          part={layer.parts[0]}
                          showLabel={false}
                        />
                      </BodySelectorCard>
                    )
                  })}
                </BodySelectorRow>
              ))}
            </BodySelectorsGrid>
          </BodyOptionsInner>
        </BodyOptionsContainer>
      </BorderContainer>
    </OptionsContainer>
  )
}

export default BodyOptions
