import create from 'zustand'
import { persist, createJSONStorage } from 'zustand/middleware'
import RandomizerTool, {
  buildLayerFromAsset,
  createBodyBaseLayers,
  createDefaultEyeLayer,
} from './randomizer-tool'
import {
  bodyPartDefinitions,
  defaultSkinSelection,
  getLayerAssetMap,
} from './dataV2.js'
import SkinColors from './skinColors'

const randomSkinIndex = Math.floor(Math.random() * SkinColors.length)
const initialBodySelection = SkinColors[randomSkinIndex]?.fileName || defaultSkinSelection
const recentTintHexLimit = 8

const normalizeRecentTintHex = (hex) => {
  if (typeof hex !== 'string') {
    return null
  }

  const sanitizedHex = hex.replace(/[^0-9a-f]/gi, '').slice(0, 6)

  if (!(sanitizedHex.length === 3 || sanitizedHex.length === 6)) {
    return null
  }

  const expandedHex =
    sanitizedHex.length === 3
      ? sanitizedHex
          .split('')
          .map((character) => `${character}${character}`)
          .join('')
      : sanitizedHex

  return `#${expandedHex.toLowerCase()}`
}

const normalizePartState = (part) => ({
  ...part,
  order: part?.order ?? null,
  tintHex: part?.tintHex ?? null,
  hueShift: part?.hueShift ?? 0,
  saturation: part?.saturation ?? 0,
  lightness: part?.lightness ?? 0,
  opacity: part?.opacity ?? 100,
  contrast: part?.contrast ?? 0,
})

const buildLegacyExistingParts = (layer) => {
  if (Array.isArray(layer?.parts) && layer.parts.length > 0) {
    return layer.parts.map((part) => normalizePartState(part))
  }

  const existingParts = []

  if (layer?.color) {
    existingParts.push({
      key: 'primary',
      selection: layer.color,
      tintHex: layer.primaryTintHex ?? null,
      hueShift: layer.primaryHueShift ?? 0,
      saturation: layer.primarySaturation ?? 0,
      lightness: layer.primaryLightness ?? 0,
      opacity: layer.primaryOpacity ?? 100,
      contrast: layer.primaryContrast ?? 0,
    })
  }

  if (layer?.secondary) {
    existingParts.push({
      key: 'secondary',
      selection: layer.secondary,
      tintHex: layer.secondaryTintHex ?? null,
      hueShift: layer.secondaryHueShift ?? 0,
      saturation: layer.secondarySaturation ?? 0,
      lightness: layer.secondaryLightness ?? 0,
      opacity: layer.secondaryOpacity ?? 100,
      contrast: layer.secondaryContrast ?? 0,
    })
  }

  return existingParts
}

const getBaseBodyColor = (layers) => {
  const bodyLayer = layers.find((layer) => layer.layerType === 'Body' && layer.isBaseLayer)
  if (bodyLayer?.parts?.[0]?.selection) {
    return bodyLayer.parts[0].selection
  }

  const legacySkinLayer = layers.find((layer) => layer.layerType === 'Skins')
  if (legacySkinLayer?.color) {
    return legacySkinLayer.color
  }

  return initialBodySelection
}

const normalizeLayer = (layer, baseBodyColor) => {
  if (!layer || layer.layerType === 'Skins') {
    return null
  }

  const builtLayer = buildLayerFromAsset(layer.layerType, layer.assetName, {
    randomizeColors: false,
    baseBodyColor,
    existingParts: buildLegacyExistingParts(layer),
  })

  if (!builtLayer) {
    return null
  }

  const normalizedAdditional = layer.additional
    ?.map((additionalLayer) => normalizeLayer(additionalLayer, baseBodyColor))
    .filter(Boolean)

  return {
    ...layer,
    ...builtLayer,
    isLocked: layer.isBaseLayer ? false : layer.isLocked ?? false,
    display: layer.display ?? true,
    isBaseLayer: layer.isBaseLayer ?? builtLayer.isBaseLayer,
    additional: normalizedAdditional?.length ? normalizedAdditional : undefined,
  }
}

const assignIds = (layers) =>
  layers.map((layer, index) => ({
    ...layer,
    id: index,
  }))

const ensureBaseBodyLayers = (layers) => {
  const incomingLayers = Array.isArray(layers) ? layers.filter(Boolean) : []
  const baseBodyColor = getBaseBodyColor(incomingLayers)
  const filteredLayers = incomingLayers.filter((layer) => layer.layerType !== 'Skins')
  const existingBodyLayers = filteredLayers.filter(
    (layer) => layer.layerType === 'Body' && layer.isBaseLayer
  )
  const existingBodyByAsset = new Map(
    existingBodyLayers.map((layer) => [layer.assetName, layer])
  )

  const normalizedBaseBodyLayers = bodyPartDefinitions
    .map((bodyPart) => {
      const existingLayer = existingBodyByAsset.get(bodyPart.assetName)
      if (existingLayer) {
        return normalizeLayer(existingLayer, baseBodyColor)
      }

      return normalizeLayer(
        {
          layerType: 'Body',
          assetName: bodyPart.assetName,
          isBaseLayer: true,
          display: true,
          isLocked: false,
          parts: [{ key: 'body', selection: baseBodyColor }],
        },
        baseBodyColor
      )
    })
    .filter(Boolean)

  const normalizedOtherLayers = filteredLayers
    .filter((layer) => !(layer.layerType === 'Body' && layer.isBaseLayer))
    .map((layer) => normalizeLayer(layer, baseBodyColor))
    .filter(Boolean)

  return assignIds([...normalizedBaseBodyLayers, ...normalizedOtherLayers])
}

const resolveSelectedLayer = (selectedLayer, layers) =>
  layers.some((layer) => layer.id === selectedLayer) ? selectedLayer : null

const mergePersistedState = (persistedState, currentState) => {
  const persisted = persistedState || {}
  const normalizedLayers = ensureBaseBodyLayers(
    Array.isArray(persisted.layerArr) ? persisted.layerArr : currentState.layerArr
  )
  const recentTintHexes = Array.isArray(persisted.recentTintHexes)
    ? Array.from(
        new Set(
          persisted.recentTintHexes
            .map((hex) => normalizeRecentTintHex(hex))
            .filter(Boolean)
        )
      ).slice(0, recentTintHexLimit)
    : currentState.recentTintHexes

  return {
    ...currentState,
    ...persisted,
    layerArr: normalizedLayers,
    selectedLayer: resolveSelectedLayer(persisted.selectedLayer, normalizedLayers),
    recentTintHexes,
  }
}

const createInitialLayers = () => {
  const baseLayers = createBodyBaseLayers(initialBodySelection)
  const defaultEyeLayer = createDefaultEyeLayer()
  const randomHair = RandomizerTool('Hair', { baseBodyColor: initialBodySelection })
  const randomUpper = RandomizerTool('Upper_Body', {
    baseBodyColor: initialBodySelection,
  })
  const randomLower = RandomizerTool('Lower_Body', {
    baseBodyColor: initialBodySelection,
  })
  const randomFeet = RandomizerTool('Feet', { baseBodyColor: initialBodySelection })

  return ensureBaseBodyLayers([
    ...baseLayers,
    ...(defaultEyeLayer ? [defaultEyeLayer] : []),
    {
      layerType: 'Feet',
      assetName: randomFeet.asset,
      parts: randomFeet.parts,
      isLocked: false,
      display: true,
    },
    {
      layerType: 'Lower_Body',
      assetName: randomLower.asset,
      parts: randomLower.parts,
      isLocked: false,
      display: true,
    },
    {
      layerType: 'Hair',
      assetName: randomHair.asset,
      parts: randomHair.parts,
      isLocked: false,
      display: true,
    },
    {
      layerType: 'Upper_Body',
      assetName: randomUpper.asset,
      parts: randomUpper.parts,
      isLocked: false,
      display: true,
    },
  ])
}

const updateLayerPartById = (layers, layerId, partKey, updater) => {
  const nextLayers = [...layers]
  const selectedLayerIndex = nextLayers.findIndex((layer) => layer.id === layerId)
  const selectedLayer = nextLayers[selectedLayerIndex]

  if (selectedLayerIndex === -1 || !selectedLayer) {
    return nextLayers
  }

  nextLayers[selectedLayerIndex] = {
    ...selectedLayer,
    parts: selectedLayer.parts.map((part) =>
      part.key === partKey ? updater(normalizePartState(part)) : part
    ),
  }

  return nextLayers
}

const updateAllLayerPartsById = (layers, layerId, updater) => {
  const nextLayers = [...layers]
  const selectedLayerIndex = nextLayers.findIndex((layer) => layer.id === layerId)
  const selectedLayer = nextLayers[selectedLayerIndex]

  if (selectedLayerIndex === -1 || !selectedLayer) {
    return nextLayers
  }

  nextLayers[selectedLayerIndex] = {
    ...selectedLayer,
    parts: selectedLayer.parts.map((part) => updater(normalizePartState(part))),
  }

  return nextLayers
}

const useLayerStore = create(
  persist(
    (set, get) => ({
      layerArr: createInitialLayers(),
      selectedLayer: null,
      addLayer: (layer) => {
        const currentLayers = get().layerArr
        const normalizedLayer = normalizeLayer(layer, getBaseBodyColor(currentLayers))

        if (!normalizedLayer) {
          return null
        }

        const nextLayers = assignIds([...currentLayers, normalizedLayer])
        set(() => ({
          layerArr: nextLayers,
        }))
        return nextLayers.length - 1
      },
      addAssetLayer: (layerType, assetName, randomizeColors = true) => {
        const baseBodyColor = getBaseBodyColor(get().layerArr)
        const newLayer = buildLayerFromAsset(layerType, assetName, {
          randomizeColors,
          baseBodyColor,
        })

        if (!newLayer) {
          return null
        }

        return get().addLayer(newLayer)
      },
      addRandomLayer: (layerType) => {
        const randomLayer = RandomizerTool(layerType, {
          baseBodyColor: getBaseBodyColor(get().layerArr),
        })

        if (!randomLayer.asset) {
          return null
        }

        return get().addLayer({
          layerType,
          assetName: randomLayer.asset,
          parts: randomLayer.parts,
          isLocked: false,
          display: true,
        })
      },
      moveLayer: (index, to) => {
        const copyArr = [...get().layerArr]
        const element = copyArr[index]
        const targetElement = copyArr[to]

        if (!element || !targetElement || element.isBaseLayer || targetElement.isBaseLayer) {
          return
        }

        copyArr.splice(index, 1)
        copyArr.splice(to, 0, element)
        set(() => ({
          layerArr: assignIds(copyArr),
        }))
      },
      updateLayer: (layer) => {
        const copyArr = [...get().layerArr]
        const layerIndex = copyArr.findIndex((item) => item.id === layer.id)

        if (layerIndex === -1) {
          return
        }

        const normalizedLayer = normalizeLayer(layer, getBaseBodyColor(copyArr))

        if (!normalizedLayer) {
          return
        }

        copyArr[layerIndex] = normalizedLayer
        set(() => ({
          layerArr: assignIds(copyArr),
        }))
      },
      setLayerArr: (layerArr) => {
        const nextLayers = ensureBaseBodyLayers(layerArr)
        set(() => ({
          layerArr: nextLayers,
          selectedLayer: resolveSelectedLayer(get().selectedLayer, nextLayers),
        }))
      },
      setSelectedLayer: (num) =>
        set(() => ({
          selectedLayer: num,
        })),
      removeLayer: () => {
        const selected = get().selectedLayer
        const copyArr = [...get().layerArr]

        if (selected === null) {
          return
        }

        const selectedLayer = copyArr.find((item) => item.id === selected)
        if (!selectedLayer || selectedLayer.isBaseLayer) {
          return
        }

        const filteredArray = copyArr.filter((item) => item.id !== selected)
        set(() => ({
          layerArr: assignIds(filteredArray),
          selectedLayer: null,
        }))
      },
      incrementAsset: () => {
        const selectedLayerId = get().selectedLayer
        const currentLayer = get().layerArr.find((layer) => layer.id === selectedLayerId)

        if (!currentLayer || currentLayer.isBaseLayer) {
          return
        }

        const assetOptions = Object.keys(getLayerAssetMap(currentLayer.layerType))
        const currentAssetIndex = assetOptions.indexOf(currentLayer.assetName)
        const nextAsset =
          currentAssetIndex === assetOptions.length - 1
            ? assetOptions[0]
            : assetOptions[currentAssetIndex + 1]

        get().setAsset(nextAsset)
      },
      setAsset: (asset) => {
        const selectedLayerId = get().selectedLayer
        const copyArr = [...get().layerArr]
        const selectedLayerIndex = copyArr.findIndex((layer) => layer.id === selectedLayerId)
        const selectedLayer = copyArr[selectedLayerIndex]

        if (selectedLayerIndex === -1 || !selectedLayer || selectedLayer.isBaseLayer) {
          return
        }

        const rebuiltLayer = buildLayerFromAsset(selectedLayer.layerType, asset, {
          randomizeColors: false,
          baseBodyColor: getBaseBodyColor(copyArr),
          existingParts: selectedLayer.parts,
        })

        if (!rebuiltLayer) {
          return
        }

        copyArr[selectedLayerIndex] = {
          ...selectedLayer,
          ...rebuiltLayer,
        }

        set(() => ({
          layerArr: assignIds(copyArr),
        }))
      },
      setLayerPartSelection: (layerId, partKey, selection) => {
        const nextLayers = updateLayerPartById(get().layerArr, layerId, partKey, (part) => ({
          ...part,
          selection,
          tintHex: null,
          hueShift: 0,
          saturation: 0,
          lightness: 0,
          opacity: 100,
          contrast: 0,
        }))

        set(() => ({
          layerArr: assignIds(nextLayers),
        }))
      },
      setPartSelection: (partKey, selection) => {
        const selectedLayerId = get().selectedLayer
        if (selectedLayerId === null) {
          return
        }

        get().setLayerPartSelection(selectedLayerId, partKey, selection)
      },
      setLayerPartTintHex: (layerId, partKey, hex) => {
        const nextLayers = updateLayerPartById(get().layerArr, layerId, partKey, (part) => ({
          ...part,
          tintHex: hex,
        }))

        set(() => ({
          layerArr: assignIds(nextLayers),
        }))
      },
      setPartTintHex: (partKey, hex) => {
        const selectedLayerId = get().selectedLayer
        if (selectedLayerId === null) {
          return
        }

        get().setLayerPartTintHex(selectedLayerId, partKey, hex)
      },
      setLayerPartColorAdjustments: (layerId, partKey, adjustments) => {
        const nextLayers = updateLayerPartById(get().layerArr, layerId, partKey, (part) => ({
          ...part,
          hueShift: adjustments.hueShift ?? part.hueShift,
          saturation: adjustments.saturation ?? part.saturation,
          lightness: adjustments.lightness ?? part.lightness,
          opacity: adjustments.opacity ?? part.opacity,
          contrast: adjustments.contrast ?? part.contrast,
        }))

        set(() => ({
          layerArr: assignIds(nextLayers),
        }))
      },
      setPartColorAdjustments: (partKey, adjustments) => {
        const selectedLayerId = get().selectedLayer
        if (selectedLayerId === null) {
          return
        }

        get().setLayerPartColorAdjustments(selectedLayerId, partKey, adjustments)
      },
      setLayerAllPartAppearance: (layerId, { tintHex = null, adjustments = {} }) => {
        const nextLayers = updateAllLayerPartsById(get().layerArr, layerId, (part) => ({
          ...part,
          tintHex,
          hueShift: adjustments.hueShift ?? 0,
          saturation: adjustments.saturation ?? 0,
          lightness: adjustments.lightness ?? 0,
          opacity: adjustments.opacity ?? 100,
          contrast: adjustments.contrast ?? 0,
        }))

        set(() => ({
          layerArr: assignIds(nextLayers),
        }))
      },
      setAllBodyColor: (selection) => {
        const nextLayers = get().layerArr.map((layer) => {
          if (!(layer.layerType === 'Body' && layer.isBaseLayer)) {
            return layer
          }

          return {
            ...layer,
            parts: layer.parts.map((part) => ({
              ...part,
              selection,
              tintHex: null,
              hueShift: 0,
              saturation: 0,
              lightness: 0,
              opacity: 100,
              contrast: 0,
            })),
          }
        })

        set(() => ({
          layerArr: assignIds(nextLayers),
        }))
      },
      setAllBodyAppearance: ({ selection = null, tintHex = null, adjustments = {} }) => {
        const nextLayers = get().layerArr.map((layer) => {
          if (!(layer.layerType === 'Body' && layer.isBaseLayer)) {
            return layer
          }

          return {
            ...layer,
            parts: layer.parts.map((part) => ({
              ...part,
              selection: selection ?? part.selection,
              tintHex,
              hueShift: adjustments.hueShift ?? 0,
              saturation: adjustments.saturation ?? 0,
              lightness: adjustments.lightness ?? 0,
              opacity: adjustments.opacity ?? 100,
              contrast: adjustments.contrast ?? 0,
            })),
          }
        })

        set(() => ({
          layerArr: assignIds(nextLayers),
        }))
      },
      randomizeUnlockedLayers: () => {
        const currentLayers = get().layerArr
        const baseBodyColor = getBaseBodyColor(currentLayers)
        const nextLayers = currentLayers.map((layer) => {
          if (layer.isBaseLayer || layer.isLocked) {
            return layer
          }

          const randomLayer = RandomizerTool(layer.layerType, {
            baseBodyColor,
          })

          if (!randomLayer.asset) {
            return layer
          }

          return {
            ...layer,
            layerType: layer.layerType,
            assetName: randomLayer.asset,
            parts: randomLayer.parts,
          }
        })

        set(() => ({
          layerArr: assignIds(nextLayers),
        }))
      },
      clearToBaseLayers: () => {
        set(() => ({
          layerArr: assignIds(get().layerArr.filter((layer) => layer.isBaseLayer)),
          selectedLayer: null,
        }))
      },
      pixels: 200,
      setPixels: (input) => {
        set(() => ({
          pixels: input,
        }))
      },
      name: '',
      setName: (input) => {
        set(() => ({
          name: input,
        }))
      },
      recentTintHexes: [],
      pushRecentTintHex: (hex) => {
        const normalizedHex = normalizeRecentTintHex(hex)

        if (!normalizedHex) {
          return
        }

        set((state) => ({
          recentTintHexes: [
            normalizedHex,
            ...state.recentTintHexes.filter((entry) => entry !== normalizedHex),
          ].slice(0, recentTintHexLimit),
        }))
      },
      searchInput: '',
      setSearchInput: (input) => {
        set(() => ({
          searchInput: input,
        }))
      },
    }),
    {
      name: 'dungeon-sprite-last',
      storage: createJSONStorage(() => sessionStorage),
      merge: mergePersistedState,
    }
  )
)

export default useLayerStore
