import React, { useEffect, useMemo, useRef, useState } from 'react'
import Canvas from '../canvas'
import ItemContainer from '../item-container/ItemContainer'
import OptionsMenu from '../options'
import useLayerStore from '../../utils/store'
import useOptionsStore from '../options/utils/options-store'
import RandomSaveContainer from '../preview/random-save'
import ConnectWithUs from '../preview/connect/connect'
import TabletHeader from '../tablet-header/tablet-header'
import Eyes from '../preview/inputs/eyes'
import Skin from '../preview/inputs/skin'
import {
  FooterShell,
  MainColumn,
  MobileHeader,
  MobileLogo,
  MobileMain,
  MobileShell,
  OptionsShell,
  PreviewCard,
  PreviewShell,
  SearchBarShell,
  SearchFieldFrame,
  SearchFieldIcon,
  SearchFieldInner,
  SearchGlyph,
  SearchInput,
  SidebarFrame,
  SidebarInner,
  SidebarCoins,
  SidebarColumn,
  SidebarUtilities,
  SidebarUtilityCard,
  SidebarUtilityInner,
  SidebarUtilityLabel,
  ToolbarShell,
} from './mobile-layout.style'

const MobileSearchButton = ({ active, onClick }) => (
  <SidebarUtilityCard type='button' active={active} onClick={onClick}>
    <SidebarUtilityInner>
      <SidebarUtilityLabel>Search</SidebarUtilityLabel>
      <SearchGlyph />
    </SidebarUtilityInner>
  </SidebarUtilityCard>
)

const MobileLayout = () => {
  const searchInput = useLayerStore((state) => state.searchInput)
  const setSearchInput = useLayerStore((state) => state.setSearchInput)
  const optionsState = useOptionsStore((state) => state.optionsState)
  const selectedLayer = useLayerStore((state) => state.selectedLayer)
  const layerArr = useLayerStore((state) => state.layerArr)
  const [searchOpen, setSearchOpen] = useState(Boolean(searchInput))
  const searchInputRef = useRef(null)

  const showToolbar = useMemo(() => {
    if (searchInput) {
      return false
    }

    const currentLayer = layerArr.find((layer) => layer.id === selectedLayer)
    return optionsState === 'item' && Boolean(currentLayer)
  }, [layerArr, optionsState, searchInput, selectedLayer])

  useEffect(() => {
    if (!searchOpen) {
      return
    }

    const timer = window.setTimeout(() => {
      searchInputRef.current?.focus()
    }, 0)

    return () => window.clearTimeout(timer)
  }, [searchOpen])

  useEffect(() => {
    if (searchInput) {
      setSearchOpen(true)
    }
  }, [searchInput])

  const toggleSearch = () => {
    if (searchOpen || searchInput) {
      setSearchOpen(false)
      setSearchInput('')
      return
    }

    setSearchOpen(true)
  }

  return (
    <MobileShell>
      <MobileHeader>
        <MobileLogo />
      </MobileHeader>
      <MobileMain>
        <SidebarColumn>
          <SidebarFrame>
            <SidebarInner>
              <SidebarCoins>
                <ItemContainer embedded />
              </SidebarCoins>
              <SidebarUtilities>
                <Eyes compact />
                <Skin compact />
                <MobileSearchButton
                  active={searchOpen || Boolean(searchInput)}
                  onClick={toggleSearch}
                />
              </SidebarUtilities>
            </SidebarInner>
          </SidebarFrame>
        </SidebarColumn>
        <MainColumn>
          <PreviewShell>
            <PreviewCard>
              <Canvas pixels={180} />
            </PreviewCard>
          </PreviewShell>
          {showToolbar && (
            <ToolbarShell>
              <TabletHeader />
            </ToolbarShell>
          )}
          <OptionsShell>
            <OptionsMenu />
          </OptionsShell>
          {(searchOpen || searchInput) && (
            <SearchBarShell>
              <SearchFieldFrame>
                <SearchFieldInner>
                  <SearchInput
                    ref={searchInputRef}
                    value={searchInput}
                    placeholder='Search'
                    onChange={(event) => setSearchInput(event.target.value)}
                  />
                  <SearchFieldIcon>
                    <SearchGlyph />
                  </SearchFieldIcon>
                </SearchFieldInner>
              </SearchFieldFrame>
            </SearchBarShell>
          )}
          <FooterShell>
            <RandomSaveContainer />
            <ConnectWithUs />
          </FooterShell>
        </MainColumn>
      </MobileMain>
    </MobileShell>
  )
}

export default MobileLayout
