import React, { useEffect, useState } from 'react'
import useLayerStore from '../../../utils/store'
import { getAssetMeta } from '../../../utils/dataV2.js'
import { getPartPreviewHex } from '../../../utils/color-display'
import DarkBorder from '../../border-container/dark-border-container'
import useOptionsStore from '../../options/utils/options-store'
import {
  CompactControls,
  EyesContainer,
  PreviewContainer,
  TextContainer,
  LeftArrow,
  RightArrow,
  ColorPreview,
  ButtonContainer,
  InnerContainer,
} from './eyes.style'

const getEyePartOrder = (part, index) => {
  const explicitOrder = Number.parseInt(part?.order, 10)

  if (Number.isFinite(explicitOrder)) {
    return explicitOrder
  }

  const keyedOrder = Number.parseInt(String(part?.key || '').split('_')[0], 10)

  if (Number.isFinite(keyedOrder)) {
    return keyedOrder
  }

  return index + 1
}

const isCyclingEyePart = (part, index) => [2, 4].includes(getEyePartOrder(part, index))

const Eyes = ({ compact = false }) => {
  const addAssetLayer = useLayerStore((state) => state.addAssetLayer)
  const setSelectedLayer = useLayerStore((state) => state.setSelectedLayer)
  const setOptionsState = useOptionsStore((state) => state.setOptionsState)
  const layerArr = useLayerStore((state) => state.layerArr)
  const updateLayer = useLayerStore((state) => state.updateLayer)
  const [hex, setHex] = useState('#393939')
  const eyeMeta = getAssetMeta('Physique', 'Etc_-_Eye_Color')
  const eyeParts = eyeMeta?.layers || []
  const cyclingEyePartMeta =
    eyeParts.find((part, index) => isCyclingEyePart(part, index)) || eyeParts[0]
  const eyeColorOptions = cyclingEyePartMeta?.colorOptions || []

  const addEyeLayer = () => {
    const eyeLayerIndex = addAssetLayer('Physique', 'Etc_-_Eye_Color', false)
    if (eyeLayerIndex !== null) {
      setSelectedLayer(eyeLayerIndex)
      setOptionsState('item')
    }
  }

  const openEyeEditor = () => {
    const eyeLayer = layerArr.find(
      (layer) => layer.assetName === 'Etc_-_Eye_Color'
    )

    if (eyeLayer) {
      setSelectedLayer(eyeLayer.id)
      setOptionsState('item')
      return
    }

    addEyeLayer()
  }

  const updateCyclingEyeParts = (currentLayer, selection) => ({
    ...currentLayer,
    parts: currentLayer.parts.map((part, index) =>
      isCyclingEyePart(part, index)
        ? {
            ...part,
            selection,
            tintHex: null,
            hueShift: 0,
            saturation: 0,
            lightness: 0,
            opacity: 100,
            contrast: 0,
          }
        : part
    ),
  })

  const incrementEyeColor = () => {
    const eyeLayer = layerArr.find(
      (layer) => layer.assetName === 'Etc_-_Eye_Color'
    )
    if (eyeLayer) {
      const currentLayer = {
        ...eyeLayer,
        parts: eyeLayer.parts.map((part) => ({ ...part })),
      }
      const currentSelection =
        currentLayer.parts?.find((part, index) => isCyclingEyePart(part, index))
          ?.selection
      const currentColorIndex = eyeColorOptions.findIndex(
        (color) => color === currentSelection
      )
      const nextSelection =
        currentColorIndex < eyeColorOptions.length - 1
          ? eyeColorOptions[currentColorIndex + 1]
          : eyeColorOptions[0]
      updateLayer(updateCyclingEyeParts(currentLayer, nextSelection))
    } else {
      addEyeLayer()
    }
  }

  const decrementEyeColor = () => {
    const eyeLayer = layerArr.find(
      (layer) => layer.assetName === 'Etc_-_Eye_Color'
    )
    if (eyeLayer) {
      const currentLayer = {
        ...eyeLayer,
        parts: eyeLayer.parts.map((part) => ({ ...part })),
      }
      const currentSelection =
        currentLayer.parts?.find((part, index) => isCyclingEyePart(part, index))
          ?.selection
      const currentColorIndex = eyeColorOptions.findIndex(
        (color) => color === currentSelection
      )
      const nextSelection =
        currentColorIndex <= 0
          ? eyeColorOptions[eyeColorOptions.length - 1]
          : eyeColorOptions[currentColorIndex - 1]
      updateLayer(updateCyclingEyeParts(currentLayer, nextSelection))
    } else {
      addEyeLayer()
    }
  }

  useEffect(() => {
    const eyeLayer = layerArr.find((layer) => layer.assetName === 'Etc_-_Eye_Color')
    const previewPart =
      eyeLayer?.parts?.find((part, index) => isCyclingEyePart(part, index)) ||
      eyeLayer?.parts?.[0]
    setHex(getPartPreviewHex(previewPart, '#393939'))
  }, [layerArr])

  return (
    <EyesContainer compact={compact}>
      <TextContainer compact={compact} className='font-face-gm'>
        Eyes
      </TextContainer>
      <CompactControls compact={compact}>
        <ButtonContainer compact={compact} onClick={() => decrementEyeColor()}>
          <InnerContainer>
            <LeftArrow compact={compact} />
          </InnerContainer>
        </ButtonContainer>
        <PreviewContainer compact={compact} onClick={openEyeEditor} style={{ cursor: 'pointer' }}>
          <DarkBorder>
            <ColorPreview compact={compact} hex={hex} />
          </DarkBorder>
        </PreviewContainer>
        <ButtonContainer compact={compact} onClick={() => incrementEyeColor()}>
          <InnerContainer>
            <RightArrow compact={compact} />
          </InnerContainer>
        </ButtonContainer>
      </CompactControls>
    </EyesContainer>
  )
}

export default Eyes
